package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.junit.jupiter.api.Assertions.*;
class TeamSliceTest { @Test void teamCreationAndJoinRequestPersist() throws Exception {Path p=Files.createTempFile("team-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("captain","password1");var captain=us.authenticate("captain","password1");var member=us.registerCustomer("member","password1");var o=new OperationsService(db);long team=o.createTeam(captain.id(),"Alpha");o.requestJoin(team,member.id());assertTrue(o.teams().get(0).contains("Alpha"));}finally{Files.deleteIfExists(p);}}}
